CALL_RE = re.compile(r'\b(skb_cow_head|skb_cow|skb_unclone|skb_share_check|pskb_expand_head|skb_linearize|skb_make_writable|pskb_may_pull|pskb_pull|__pskb_pull_tail)\s*\(')

def load(path):
    with open(os.path.join(ROOT, path), errors='replace') as fh:
        return fh.read().split('\n')

def find_functions(lines):
    # naive function start detection: line matching at col0: type name(...) or name(...) with following { or same line
    starts = []
    for i, ln in enumerate(lines):
        if re.match(r'^[A-Za-z_][A-Za-z0-9_ \t\*]*\(', ln) or re.match(r'^(static|inline|unsigned|void|int|bool|struct|u8|u16|u32|u64|__be16|__be32|s8|s16|s32|char|const|enum|long|size_t|sk_buff|netdev|napi|dx|)', ln):
            m = re.match(r'^([A-Za-z_][A-Za-z0-9_ \t\*]*?)\s*\(', ln)
            if m and ('(' in ln):
                name = m.group(1).split()[-1]
                # ensure a body follows
                j = i
                depth = 0
                started = False
                # find opening brace within this line or next few lines
                text = ln
                if '{' in text:
                    starts.append((i+1, name))
                    continue
                for j in range(i, min(i+4, len(lines))):
                    if '{' in lines[j]:
                        starts.append((i+1, name))
                        break
                    if ';' in lines[j] and j != i:
                        break
    return starts

results = []
with open(os.path.join(W, 'files.txt')) as fh:
    files = [l.strip() for l in fh if l.strip()]

for path in files:
    try:
        lines = load(path)
    except Exception as e:
        print("ERR", path, e); continue
    starts = find_functions(lines)
    # for each call line, find enclosing function
    for i, ln in enumerate(lines):
        m = CALL_RE.search(ln)
        if not m: continue
        # find enclosing function: last start before i
        fn = None
        for (ls, name) in starts:
            if ls <= i+1:
                fn = (ls, name)
            else:
                break
        if fn is None: continue
        fs, fname = fn
        # function span until next function start
        idx = starts.index(fn)
        end = starts[idx+1][0]-1 if idx+1 < len(starts) else len(lines)
        body = lines[fs-1:end]
        # find local pointer-like declarations before the call within body
        decls = []
        for k, bl in enumerate(body):
            dm = re.match(r'^\t(?:static\s+)?(?:const\s+)?(?:struct\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\*+\s*([A-Za-z_][A-Za-z0-9_]*)', bl)
            if dm and dm.group(1) in ('iph','ipv6h','tcph','udph','icmph','hdr','skb','ethhdr','iphdr','tcphdr','udphdr','icmphdr','arphdr','iphdr_t','gre_base_hdr','vlan_hdr','llchdr','pppoh','struct','u8','unsigned','char','__be16','__be32','iphdr','ipv6hdr'):
                decls.append((fs+k, dm.group(2)))
        if not decls: continue
        # find assignments to those names and uses after call line within body
