                    use_after.append((lineno, bl.strip()[:120]))
            if assign_lines and use_after:
                results.append({
                    'file': path, 'func': fname, 'func_line': fs,
                    'call_line': i+1, 'call': ln.strip()[:120],
                    'ptr': name, 'assign': assign_lines,
                    'uses_after': use_after[:8],
                })

